#include <bits/stdc++.h>
using namespace std;

long long fast_pow(long long base, long long exp) {
    long long result=1;
    while (exp>0) {
        if (exp & 1) result=(result*base)%1000000007;
        base=(base*base)%1000000007;
        exp>>=1;
    }
    return result;
}

struct DisjointSet {
    vector<int> parent, rank;
    int total_components;
    DisjointSet(int n): parent(n), rank(n,0), total_components(n) {
        for (int i=0; i<n; ++i) parent[i]=i;
    }
    int find(int u) {
        if (parent[u]!=u) parent[u]=find(parent[u]);
        return parent[u];
    }
    void merge(int u, int v) {
        u=find(u); v=find(v);
        if (u!=v) {
            if (rank[u]<rank[v]) swap(u,v);
            parent[v]=u;
            if (rank[u]==rank[v]) ++rank[u];
            --total_components;
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long p, k;
    cin>>p>>k;
    vector<bool> visited(p,false);
    DisjointSet ds(p);
    for (long long i=0; i<p; ++i) {
        for (long long j=i; !visited[j]; j=(j*k)%p) {
            visited[j]=true;
            ds.merge(i,j);
        }
    }
    int c=ds.total_components;
    if (k!=1) c--;
    cout<<fast_pow(p,c)<<endl;
    return 0;
}
